                T + "10:00:00Z", T + "11:00:00Z", 60, "改原因"), null, 409);

        // 换 commandKey 但同 requestId 同参 -> 重放首次结果（受影响排班与新窗口一致）
        JsonNode replayOtherCommand = postOk("/api/outages",
