                null);
        assertEquals(first, replayOtherCommand);
        assertEquals(1, getOk("/api/channels/" + channel + "/outages").get("outages").size());
        assertEquals(1, jdbc.queryForObject("SELECT COUNT(*) FROM schedule_postponement", Integer.class));
