    assertEquals(T + "11:00:00Z",
            retry.get("postponements").get(0).get("newStartUtc").asText());
    assertEquals(T + "12:00:00Z", retry.get("postponements").get(0).get("newEndUtc").asText());
    assertEquals(0, scheduleOutageCrossingCount(channel));
    assertEquals(0, scheduleOverlapPairCount(channel));
}

